1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
하나님: 1(2), 2, 3(2), 4, 9
예수: 1, 2, 3
그리스도: 1, 2, 3, 5(2)
환난: 4(2), 6, 8
위로: 4(3), 5, 6(4), 7
고난: 5, 6, 7, 8

4.주제 만들기: 극심한 고난과 하나님이 주시는 위로

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 편지를 통해 교회에 인사하는 바울과 디모데
- 하나님은 모든 환난 중에서 우리를 위로하시는 분이시다 
- 그리스도의 고난이 우리에게 넘친 것 같이 그리스도로 말미암아 받는 위로도 넘친다
- 우리가 환난을 당하는 것도 위로를 받는 것도 모두 너희를 위로받게 하려는 것이다
- 너희를 위한 소망이 견고하다
- 우리가 아시아에서 살 소망이 끊어질 정도의 환난을 당했으나 이것은 죽은 자를 다시 살리시는 하나님을 의지하게 하심이라
- 하나님은 큰 사망에서 우리를 건지셨고 또 건지실 것이며 이 후에도 건지시기를 그에게 바란다 

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 바울과 디모데가 그리스도의 복음과 교회를 위해 얼마나 큰 고난들을 당했는지 알 수 있다.
- 바울은 살 소망이 없어졌다고 느낄 만큼 고난을 당했다.
- 바울과 같이 강력한 믿음의 소유자가 살 소망이 없어졌다고 느낄 정도이면 그 고난의 깊이는 상상을 초월하는 것일 것이다
- 바울은 그 고난을 해석하기를 사람이 자기 자신을 의지하지 않고 하나님만을 의지하게 하신 하나님의 뜻이라고 해석한다
- 그리고 이것을 그리스도로 말미암은 위로라고 말한다

- 고난 받는 상황을 불평하지 않고 하나님만을 의지하는 수단으로 해석하고 나아가 자신의 고난이 다른 이를 위로하는 수단이 된다고 해석하고 있는 것이다

9.적용(나) 
- 나의 고난도 그리스도로 말미암아 위로가 넘친다
- 내가 버틸 수 없는 상황을 만날 때 비로소 하나님만 의지할 수밖에 없음을 절실히 깨닫게 된다.
- 신자는 도우시는 하나님을 바라며 살아갈 수밖에 없다.
- 또한 나의 고난이 또 다른 신자에게 위로가 될 것을 기대한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-03-03', '고린도전서', '16장 11~24절', '믿음 위에 굳게 서고, 믿음으로 행하라', '[고전16:11-24]
11 그러므로 누구든지 그를 멸시하지 말고 평안히 보내어 내게로 오게 하라 나는 그가 형제들과 함께 오기를 기다리노라
12 형제 아볼로에 대하여는 그에게 형제들과 함께 너희에게 가라고 내가 많이 권하였으되 지금은 갈 뜻이 전혀 없으나 기회가 있으면 가리라
13 깨어 믿음에 굳게 서서 남자답게 강건하라
14 너희 모든 일을 사랑으로 행하라
15 형제들아 스데바나의 집은 곧 아가야의 첫 열매요 또 성도 섬기기로 작정한 줄을 너희가 아는지라 내가 너희를 권하노니
16 이같은 사람들과 또 함께 일하며 수고하는 모든 사람에게 순종하라
17 내가 스데바나와 브드나도와 아가이고가 온 것을 기뻐하노니 그들이 너희의 부족한 것을 채웠음이라
18 그들이 나와 너희 마음을 시원하게 하였으니 그러므로 너희는 이런 사람들을 알아 주라
19 아시아의 교회들이 너희에게 문안하고 아굴라와 브리스가와 그 집에 있는 교회가 주 안에서 너희에게 간절히 문안하고
20 모든 형제도 너희에게 문안하니 너희는 거룩하게 입맞춤으로 서로 문안하라
21 나 바울은 친필로 너희에게 문안하노니
22 만일 누구든지 주를 사랑하지 아니하면 저주를 받을지어다 우리 주여 오시옵소서
23 주 예수 그리스도의 은혜가 너희와 함께 하고
24 나의 사랑이 그리스도 예수 안에서 너희 무리와 함께 할지어다

