- 가리어지다(3절)
- 그리스도(4,5,6절)
- 영광(4,6절)
- 빛(6절)
- 아니하며(8,9절)

4. 주제만들기: 낙심하지 말라

5. 하나님 찾기 (관찰)
- 긍휼하심으로 직분을 주신 하나님

6. 인간 찾기 (관찰)
- 부끄러운 일을 버렸고, 속임을 행하지 아니하였으며, 하나님의 말씀을 혼잡스럽게 하지 않고, 진리를 나타냄으로 하나님 앞에서 우리 스스로를 추천한다고 말하는 바울
- 복음은 망한자들에게 가려진 것이고, 세상의 신이 그들의 마음을 혼미하게 하여 그리스도의 영광스러운 복음의 빛이 그들에게 비치지 못하게 한 것이라 말하는 바울
- 우리는 그리스도 예수가 주 되신 것과 여러분의 종이 된 것을 전파한다고 말하는 바울
- 우리는 보배를 질그릇에 갖고 있고, 하나님의 능력이 우리에게 난 것이 아님을 보여주려는 것이라 말하는 바울
- 어떠한 일이 있어도 낙심하지 않는다 말하는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 우리는 질그릇에 하나님의 보배(능력)을 담고 있다.
- 언제든, 그리고 쉽게 깨질 수 있는 질그릇은 우리의 연약함을 나타낸다.
- 그릇 중 잘 깨지는 것이 있다면 어떻게 하겠는가? 사용하지 않거나 버릴 것이다.
- 그런데 하나님은 질그릇과 같은 우리에게 하나님의 능력을 부어주셨다. 
- 질그릇은 여러 가지를 생각할 수 있는데, 첫 번째는 우리는 교만하면 언제든 무너질 수 있는 존재이다. 
- 하나님을 믿는 믿음 안에서 신앙생활을 하다보면 나도 모르게 생기는 교만함이 있다. 교만함은 우리를 무너뜨리고 우리의 그릇을 깨뜨릴 것이다. 즉 하나님의 능력은 언제든 우리 안에서 흘러버릴 수 있다는 것이다. 
- 두 번째는 그럼에도 불구하고 하나님은 우리를 사용하신다는 것이다. 
- 질그릇처럼 쉽게 깨지는 존재임에도 하나님은 우리를 사랑하시고, 그분의 능력으로 우리를 보호하시며, 우리를 일으켜 세우시는 분이시다. 

- 하나님을 만난 우리가, 당연히 모든 면에서 승리하고, 만사형통한 삶을 살아갈 것이라 생각하는 경우가 많다. 
- 그러나 우리의 삶에 사탄의 공격이 얼마나 많은지 생각해보아야 한다. 
- 사탄의 공격은 각자 다를 것이다.
- 그럴 때 우리는 질그릇임을 기억하자. 우리의 능력으로 사탄에게 맞서는 것이 아니라 
- 질그릇을 사용하는 주인이 얼마나 조심하며 그 그릇을 다룰지 믿으면 된다.
- 하나님께선 우리를 귀하게 여기신다. 하나님의 능력을 의지하고 신뢰하며 담대하게 나아갈 수 있는 믿음이 우리에게 필요하다.
- 우리는 결국 승리할 것이다.

9. 적용(나): 
