- 바울은 하나님의 두려움을 알기에 사람들을 권면하고 그리스도의 사랑이 강권한다고 말한다
- 하나님을 알고 믿고 끝나는 것이 아니라 그것을 모르는 자들에게 전하는 것이다.
- 그리스도의 사랑이 바울을 강권하여 사람들에게 그리스도를 전하게 한다
- 그리스도는 모든 사람(특히 이 말을 듣는 사람)을 위해 죽으셨다
- 그가 죽으심은 죄지은 모든 사람이 죽은 것과 같다.
- 그가 죄지은 모든 사람을 위하여 죽으심은 이제 그리스도를 위하여 살게 하려 하심이다
- 그를 위하여 산다는 것은 이제 자신을 위한 삶을 사는 것이 아니라,
- 그리스도의 사랑을 알고, 그 사랑 안에서 삶을 누리며, 또한 그 사랑에 못 이겨 그 사랑을 전하는 삶일 것이다.
- 그러므로 우리는 새로운 피조물이다 자신을 위해 살던 나는 사라지고 그리스도를 위하여 사는 나로 새롭게 태어났다

- 모든 것은 하나님께로부터 나왔고 하나님은 그리스도로 말미암아 자기와 우리를 화목하게 하셨다
- 또한 우리에게 화목하게 하는 직분을 주셨다
- 이 직분은 이 진리를 모르는 사람들 또한 하나님과 화목하게 하기 위하여 그들에게 그리스도를 전하는 직분이다 
- 하나님은 세상 사람들의 죄를 그들에게 돌리지 않고 그들과 화목하기 위한 말씀(속죄, 구원하기 위한 말씀)을 우리에게 부탁하셨다
- 이제 우리는 그리스도를 대신한 사신으로서 너희에게 간절히 말한다
- 너희는 하나님과 화목하라 
- 하나님께서 죄가 없으신 하나님의 아들을 우리를 대신하여 죄로 삼으신 것은 우리를 그리스도 안에서 하나님의 의가 되게 하신 것이다.
- 우리는 하나님의 크신 사랑 안에서, 은혜로 하나님의 의가 되었다.
- 우리가 의로운 것이 아니라 하나님의 의가 우리에게 입혀진 것이다.

9.적용(나) 
- 신자는 그리스도를 위하여 사는 새로운 피조물로서 살아가야 한다.
- 그리스도의 사신으로서 살던 사도들을 계승하여 나 또한 그리스도의 사신으로 살아가야 한다.
- 내가 의롭게 살아서 의로운 것이 아니라, 하나님의 은혜로 하나님의 의가 되었음을 기억해야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

