6. 인간 찾기 (관찰)
- 하나님의 뜻대로 하게 된 근심은 우리를 깨끗게 하였다고 말하는 바울
- 이 편지는 불의를 위한 사람과 불의를 당한 사람을 위해 쓴 것이 아니라 너희의 간절함이 하나님 앞에 나타나도록 하기 위함임을 말하는 바울
- 이로 인해 위로를 받았으며, 디도를 통해 기쁨을 얻게 된 바울
- 디도를 두려움과 떪으로 영접한 것과 순종한 것을 기뻐하며 신뢰하게 되었음을 말하는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 오늘 말씀은 두가지를 생각해보게 된다. 첫번째는 하나님의 뜻을 쫓아 살아가는 우리는 하나님의 말씀을 통해 근심하는 삶을 살고 있는가?이다.
- 나는 얼마나 간절하게 하나님을 사모하고 있을까? 얼마나 간절하게 하나님의 말씀과 하나님과 함께하는 기도의 시간과 하나님께 영광을 드리는 찬양을 드리고 있을까? 
- 나는 얼마나 회개하는 삶을 실천하고 있을까? 나는 얼마나 죄를 벗어나려 발버둥치고 있을까?
- 나는 얼마나 하나님을 경외하고 사모하고 열심을 다해 사명을 감당하고 있을까? 
- 뼈 때리는 질문에 한숨만 나온다. 그러나 이것은 나에 대한 정죄함이 아닌 하나님께 나아가는 동기가 될 것이다. 위의 질문에 소리쳐 대답할 수 있는 사람이 되도록 은혜를 주시길 기도해야겠다. 분명한 사실은 나의 능력으론 불가능하다.

- 두 번째는 내 안에 두려움과 떪으로 하나님의 목자 앞에 순종함을 보이는 태도가 있는지이다. 내 안에 얼마나 많은 교만이 있는지 생각해보게 된다. 성도를 돌보는 목자를 진심으로 존경하는 마음이 내 안에 가득하길 기도한다.

9. 적용(나):
