2026년 03월 15일 
고린도 후서 7장 1절~10절
1.1분기도
2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:
위로: 6절(2) 7절 
근심: 8절(2) 9절(3) 10절(2)
