- 나 또한 나를 버림으로 내 주변의 신자를 구제하고 섬길 수 있는 것이다.
- 은혜 안에서 내가 할 수 있는 것을 내 주변 사람들을 위해 기쁨으로 실천해야겠다.
- 주님의 은혜가 나와 내 주변 사람들에게 넘치기를 바란다.

