2026년 03월 25일 
고린도 후서 11장 21절~33절
1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미 찾기:
약하면/약하지/약한 것: 21절 29절 30절
맞고/맞았으며: 23절 24절 25절 
