- 예루사렘에서 이방사람들에게 전하는 복음에 대하여 설명하였다
- 디도는 헬라인이었으나 할례를 강요 받지 않았다
- 거짓 신도들이 할례를 강요하는 일이 있었으나 그들에게 굴복하지 않았다
- 유명한 사람들에게 어떤 제안도 받지 않았다
- 도리어 그들은 베드로가 유대인에게 복음을 전하는 사도직을 받은 것처럼 바울은 이방인에게 복음을 전하는 사도직을 받았다는 사실을 깨달았다
- 바울과 바나바는 예루살렘 교회에서 기둥처럼 여기는 야고보, 베드로, 요한과 친교의 악수를 하였고
- 바울과 바나바는 이방 사람에게, 야고보, 베드로, 요한은 유대인에게 가기로 함
- 그들은 가난한 자를 기억해 달라고 요구하였는데, 그것은 바울과 바나바도 힘써 해오던 일이었다

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 바울과 바나바가 무려 십사 년이 지난 후에 예루살렘 교회로 돌아왔다
- 무려 십사 년 동안 말씀을 연구하고 가르치고 교회를 세우고 전도한 것이다
- 십사 년 뒤에 예루살렘으로 온 것도 인간의 마음이 아니라, 계시를 받고 온 것이다
- 계시가 없었다면 고향 땅을 밟지 않았을지도 모른다

- 예루살렘에서 회의가 열렸고 이 회의에서 바울은 이방인에게 복음을 전하는 사도직을 예수님께 부여 받았음을 인정받았고, 베드로, 요한, 야고보와 친교의 악수를 하였다.
- 바울은 예루살렘의 공식적인 자리에서 사도로 공인을 받은 것이다.

- 바울은 공식적으로 대표적인 살인마에서 공식적인 사도가 되었다.

- 예수님의 공생애를 함께 하며 가난한 자 돌보는 것을 배운 사도들이 바울과 바나바에게 가난한 자를 돌볼 것을 요청하였고,
- 바울 또한 가난한 자 돌보는 일에 마음을 다하고 있었다.
- 부활하신 예수님이 직접 만나주시고 성령 충만함을 받아 성령님의 계시를 받는 바울 또한 사도들과 같은 마음으로 가난한 자들을 돌보고 있었던 것이다.
- 가난한 자를 돌보는 것은 신자로서 마땅히 할 일이다.  

9.적용(나) 
- 바울과 바나바를 십사 년을 뒤돌아보지 않고 묵묵하게 말씀을 가르치고 전도하였다.
