5. 하나님 찾기 (관찰)
- 우리를 위하여 예수님을 이 땅에 보내신 하나님
- 우리를 위하여 저주를 받으신 예수님
- 미리 정하신 언약으로 예수님을 보내실 것을 약속하신 하나님

6. 인간 찾기 (관찰)
- 율법은 믿음에서 난 것이 아니고 율법을 의지하는 자는 그 안에 살 것이라 말하는 바울
- 예수 그리스도의 십자가를 통해 율법의 저주에서 우리를 속량하셨다 말하는 바울
- 그리스도 예수 안에서 아브라함의 복이 이방인에게 미치게 하고 우리를 통해 믿음으로 성령의 약속을 받게 함이라 말하는 바울

7. 하나님 찾기 (해석) 
- 하나님께선 창조부터 구원까지 모든 것을 예비하셨다. 인간에게 자유 의지가 없고, 하나님을 찬양하는 존재로 만드셨다면 이런 번거로운 일은 하지 않아도 되었을 것이다. 그렇다면 우리 인간에겐 드라마틱한 삶은 주어지지 않았을 것이다. 우리는 감정이 제한적일 것이고, 그러한 삶이 온전한 삶이라 말하긴 어려울 것 같다.
- 번거로운 일은 예수님을 예비하신 것이다. 하나님이신 자신이 인간의 몸으로 이 땅에 오셔서 희생 제물이 되셨다. 이를 통해 인간은 구원 받을 수 있었고, 인간이 만든 잘못된 율법 안에서 벗어날 수 있게 되었다. 하지만 아직도 잘못된 율법 안에 갖힌 영혼이 많다.
- 이 사실을 알게 되고 믿게 하시는 것도 하나님의 은혜이다. 그러므로 우리는 죄인이고, 예수님을 통해 구원 받았으며, 율법에서 벗어나 하나님을 의지하는 존재로 살아갈 수 있게 된 것에 감사하다.

8. 인간(해석):
- 바울의 입장에서 예수님을 제대로 알지 못하는 수많은 영혼을 보면 얼마나 안타까웠을까? 과거나 현재나 동일하게 같은 어려움을 겪고 있다. 그리고 비슷한 문제가 교회 안에서 늘 발생한다. 그렇기 때문에 성경을 바르게 이해하고 해석하는 것이 매우 중요하다고 느껴진다. 
- 바울 당시에 현대와 같이 성경이 보급되었다면 이 시대는 많이 변했을 것 같다. 그러나 마음만 먹으면 성경을 볼 수 있는 이 시대에 사는 우리는 여전히 같은 문제에 놓여있다. 심지어 이단이 더 성경을 이용하고 있는 상황이다. 
- 우리가 매일 4년여간 이어온 3331 큐티가 얼마나 귀한지 깨닫는다. 

9. 적용(나): 
- 3331 큐티를 이어오게 하신 하나님께 감사와 찬양과 영광을 올려드린다.
- 예수님을 내가 먼저 제대로 알고 전할 수 있도록 더욱 노력해야겠다.

10. 영적터치(단어/구절)
- 예수 그리스도

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-04-04', '갈라디아서', '3장 21~29절', '제목 없음', '(갈라디아서 3장)
21. 그러면 율법이 하나님의 약속들과 반대되는 것이냐 결코 그럴 수 없느니라 만일 능히 살게 하는 율법을 주셨더라면 의가 반드시 율법으로 말미암았으리라
22. 그러나 성경이 모든 것을 죄 아래에 가두었으니 이는 예수 그리스도를 믿음으로 말미암는 약속을 믿는 자들에게 주려 함이라
23.  믿음이 오기 전에 우리는 율법 아래에 매인 바 되고 계시될 믿음의 때까지 갇혔느니라
24. 이같이 율법이 우리를 그리스도께로 인도하는 초등교사가 되어 우리로 하여금 믿음으로 말미암아 의롭다 함을 얻게 하려 함이라
25. 믿음이 온 후로는 우리가 초등교사 아래에 있지 아니하도다
26. 너희가 다 믿음으로 말미암아 그리스도 예수 안에서 하나님의 아들이 되었으니
27. 누구든지 그리스도와 합하기 위하여 세례를 받은 자는 그리스도로 옷 입었느니라
28. 너희는 유대인이나 헬라인이나 종이나 자유인이나 남자나 여자나 다 그리스도 예수 안에서 하나이니라
29. 너희가 그리스도의 것이면 곧 아브라함의 자손이요 약속대로 유업을 이을 자니라

