갈라디아서 3장 21절~29절
1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미 찾기:
율법: 21절(2) 24절 
믿음: 22절(2) 23절(2) 24절 25절 26절 
