2026년 04월 05일 
갈라디아서 4장 1절~10절
1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미 찾기:
종/종 노릇: 3절 7절 8절 9절
아빠/아버지: 2절 6절
아들: 4절 5절 6절 7절(2) 
