어렸을 동안/ 정한 때까지: 1절 2절
율법 아래: 4절 5절
유업: 1절 7절 
   
4. 주제:
종에서 상속자로 바뀐 신분    

5. 하나님 찾기(관찰)
죄인을 자신의 상속자(아들)로 삼으시는 하나님 아버지 

6. 인간 찾기(관찰)
종노릇 하는 인간
종에서 하나님의 상속자가 된 신자  

7. 하나님 찾기(해석)
바울은 인간의 본질에 대해 분명하게 말한다. 인간은 본래 하나님이 아닌 것들, 곧 우상과 마귀, 그리고 율법주의의 종으로 살아가던 존재였다. 

그러나 하나님께서는 그러한 비진리 가운데 있던 사람들을 용서하시고, 오히려 하나님의 유업을 이어받을 상속자로 삼아 주셨다. 이 얼마나 놀라운 은혜인가!

이 사실은 인간의 이성으로는 도저히 납득하거나 온전히 이해하기 어려운 하나님의 사랑이다. 

바울은 이 크고 깊은 은혜를 강조하기 위해 때로는 역설적인 표현까지 사용한다. 

갈라디아서 4장 9절에서 “어찌하여 다시 약하고 천박한 초등학문으로 돌아가서 다시 그들에게 종노릇 하려 하느냐”라고 외치는 그의 음성은 지금도 귀에 울리는 듯하다.

그렇다면 거룩하시고 정의로우신 하나님께서는 왜 어둠 가운데 갇혀 있던 죄인들을 구원하시어, 단순한 종이 아니라 자기 아들, 곧 상속자의 신분으로까지 높여 주셨을까? 

양보하여 생각해 보더라도, 충성된 종으로만 받아 주셨어도 충분하지 않았을까 하는 질문이 자연스럽게 떠오른다.

이 질문에 대해 인간은 당장 완전한 답을 내릴 수 없다. 

그러나 한 가지 분명한 사실은 하나님은 사랑이시라는 점이다. 

이해를 초월하는 그 사랑으로 하나님께서는 인간에게 구원과 자유를 주셨을 뿐 아니라, 자녀라는 놀라운 신분까지 허락하셨다.

8. 인간 찾기(해석)

9. 적용 (구체적으로)
사랑의 본을 가장 분명하게 보여 주신 분이 바로 독생자 예수 그리스도이시다. 

죄인을 위해 죽으시고 다시 살아나신 주님께서는 지금도 선한 길로 인도하시며 큰 위로와 기쁨이 되신다.
특별히 오늘은 부활주일이다. 

죽으에서 승리하사 다시 살아나신 주님을 더욱 깊이 묵상하며, 찬양을 올려 드려야 하겠다.

10. 영적 터치 (단어/구절)
9절: 다시 그들에게 종노릇 하려 하느냐?

11. 믿음과 회개 및 감사 기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-04-07', '갈라디아서', '4장 21~31절', '사라와 하갈&nbsp;', '갈라디아서 4장
21   내게 말하라 율법 아래에 있고자 하는 자들아 율법을 듣지 못하였느냐
22   기록된 바 아브라함에게 두 아들이 있으니 하나는 여종에게서, 하나는 자유 있는 여자에게서 났다 하였으며
23   여종에게서는 육체를 따라 났고 자유 있는 여자에게서는 약속으로 말미암았느니라
24   이것은 비유니 이 여자들은 두 언약이라 하나는 시내 산으로부터 종을 낳은 자니 곧 하갈이라
25   이 하갈은 아라비아에 있는 시내 산으로서 지금 있는 예루살렘과 같은 곳이니 그가 그 자녀들과 더불어 종 노릇 하고
26   오직 위에 있는 예루살렘은 자유자니 곧 우리 어머니라
27   기록된 바 잉태하지 못한 자여 즐거워하라 산고를 모르는 자여 소리 질러 외치라 이는 홀로 사는 자의 자녀가 남편 있는 자의 자녀보다 많음이라 하였으니
28   형제들아 너희는 이삭과 같이 약속의 자녀라
29   그러나 그 때에 육체를 따라 난 자가 성령을 따라 난 자를 박해한 것 같이 이제도 그러하도다
30   그러나 성경이 무엇을 말하느냐 여종과 그 아들을 내쫓으라 여종의 아들이 자유 있는 여자의 아들과 더불어 유업을 얻지 못하리라 하였느니라
31   그런즉 형제들아 우리는 여종의 자녀가 아니요 자유 있는 여자의 자녀니라

