- 예수님의 십자가 사역 없이는 이방인의 구원은 불가능한 것이었기 때문이다
- 이것은 유대인과 이방인을 그리스도 예수 안에서 한 몸이 되어 하나님과 화목하게 하신 것이다

8.인간 찾기(해석)
