4. 주제:
어떠한 역할을 하든지 주 안에서 행하라

5. 하나님 찾기(관찰)
장수케 하시는 하나님
하늘에 계시는 상전 되신 하나님
능력의 주님


6. 인간 찾기(관찰)
자녀들은 부모에게 순종하라
아비들은 자녀를 노엽게 하지 말라
종들은 상전에게 순종하라
상전은 종들을 위협하지 말라

7. 하나님 찾기(해석)
 
8. 인간 찾기(해석)
사도 바울은 보이지 않는 영적 세계뿐 아니라, 우리가 살아가는 육체적인 관계 속에서도 하나님 자녀로서 어떻게 살아가야 하는지를 분명하게 보여준다. 

그는 부모와 자녀, 종과 상전이라는 구체적인 관계 안에서 각자가 어떠한 태도로 서로를 대해야 하는지를 가르친다. 

이는 단순한 윤리적 권면이 아니라, 하나님과의 관계에서 비롯된 삶의 방식이다.

본문을 묵상하다 보면 한 가지 뚜렷한 공통점을 발견하게 된다. 모든 관계의 기준과 출발점이 ‘주님과의 연결’에 있다는 사실이다. 

1절에서는 ‘주 안에서’, 4절에서는 ‘주의 교훈과 훈계로’, 5절에서는 ‘그리스도께 하듯’, 9절에서는 ‘상전이 하늘에 계심을 알고’라고 말한다. 이 표현들은 우연히 나열된 것이 아니라, 바울의 분명한 의도가 담긴 선언이다.

곧 하나님이 기뻐하시는 자녀의 삶은 인간적인 노력이나 도덕적 결심에서 시작되는 것이 아니라, ‘주 안에 거하는 것’에서부터 출발한다. 주님과의 바른 관계가 먼저 세워질 때, 비로소 참된 사랑이 흘러나오고, 그 사랑 안에서 건강한 인간관계가 형성된다. 

부모와 자녀의 관계, 윗사람과 아랫사람의 관계 역시 하나님을 향한 사랑과 순종에서 자연스럽게 바로 서게 된다.

결국 하나님은 모든 관계의 근원이자 끊임없이 생명을 공급하시는 분이다. 

마치 무한한 에너지를 공급하는 발전소와 같이, 하나님과의 연결이 끊어지지 않을 때 우리의 삶은 흔들리지 않는다. 

그러므로 지혜로운 사람은 먼저 자신의 참된 상전 되시는 주님과 동행하는 삶을 선택한다. 

그 동행 속에서 삶의 모든 관계가 새롭게 정돈되고, 하나님이 기뻐하시는 질서와 사랑이 온전히 드러난다.

9. 적용 (구체적으로)
오늘은 남청연 리더그룹과 더불어 등산하며 힐링의 시간을 가졌다. 

아름다운 자연을 보며 전능하신 하나님의 작품에 큰 감명을 받았다. 

무엇보다 생명을 주시고 관리하시는 대자연의 주인이신 하나님 안에 거하며 잠시 맡겨주신 영혼들을 소중히 여기며 순종하며 기쁨으로 잘 섬겨야겠다고 다짐한다.

10. 영적 터치 (단어/구절)
10절: 너희가 주 안에서와 그 힘의 능력으로 강건하여지고

11. 믿음과 회개 및 감사 기도로 마무리하기

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

