2026년 05월 9일 
골로세서 1장 21절~29절
1.1분기도
2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:
복음: 23절(3) 
비밀: 26절 27절 
영광: 27절(2)
그리스도/그리스도 안: 24절 27절 28절 

4. 주제:
복음의 비밀

5. 하나님 찾기(관찰)
화목케 하시는 그리스도
죽으신 예수
직분을 주시는 하나님
영광의 소망이신 그리스도

6. 인간 찾기(관찰)
복음의 일꾼이 된 바울
그리스도 안에서 세워져 가는 신자들 

7. 하나님 찾기(해석)
사도 바울이 기록한 짧은 구절 속에는 복음의 핵심이 잘 담겨 있다.

악한 행실로 하나님과 원수 되었던 사람들을 살리기 위해 예수님께서 대신 죽으셨다. 그리고 그 죄인들을 흠 없는 백성으로 세우시고자 하나님과 화목하게 하셨다. 

이것이 바울이 말하는 복음인데, 참 놀랍게도 이 복음은 매일 들어도 전혀 질리지 않는다.

새벽에 일어나 다시 이 단순한 진리를 묵상해 보았다.

거룩하시고 완전하신 주님은 왜 원수 된 죄인을 살리기 위해 자신을 희생하셨을까?

우리와 함께 화목하기를 원하셔서일까?

아니면 심혈을 기울여 지으신 특별한 존재인 인간을 차마 버릴 수 없으셨기 때문일까?

혹은 하늘나라에서 반역한 사탄에 대한 하나님의 뜻이 담겨 있는 것일까?

오늘 말씀을 묵상하면서 한 가지 분명히 느껴지는 것은, 하나님께서 우리와 동행하기를 원하신다는 사실이다. 단순히 죄를 용서하시는 것에서 끝나는 것이 아니라, 우리를 주님 안에서 완전한 자로 세우기를 원하시는 것 같다.

28절 말씀에도 이렇게 기록되어 있다.
“각 사람을 그리스도 안에서 완전한 자로 세우려 함이라.”

하나님의 헤아릴 수 없는 사랑이 얼마나 크시기에, 하나님께서 누리시는 영광과 기쁨을 죄인 된 우리와도 함께 나누기 원하시는 것일까?

심지어 흠 많고 연약한 사람들을 자녀 삼으시면서까지 말이다.

이처럼 놀라운 복음은 인간의 생각과 말로 다 설명하기 어려운 것 같다. 그래서 바울도 만세 전부터 감추어졌던 하나님의 구원을 “비밀”이라는 단어로 표현하지 않았나 생각해 본다.

8. 인간 찾기(해석)
 
9. 적용 (구체적으로)
오늘 난지 한강공원에서 기도를 올릴 때 마음속에 크신 하나님의 사랑을 느꼈다. 사랑이 얼마나 크게 다가오는지 감당하기 어려울 정도였다. 

평생 거대한 주님 사랑 안에 거하며 배신하지 않고 감사하며 살겠노라고 다짐한다. 더욱 굳센 믿음 위해 기도를 올려야겠다.

10. 영적 터치 (단어/구절)
27절: 이 비밀은 너희 안에 계신 그리스도시니 곧 영광의 소망이니라

