5. 하나님 찾기(관찰)
보화이신 예수
모든 통치와 권세의 머리이신 그리스도

6. 인간 찾기(관찰)
예수 안에서 굳건한 믿음을 가질 것을 권면하는 바울

7. 하나님 찾기(해석)

8. 인간 찾기(해석)
바울은 믿음에 굳게 서서 감사함이 넘치도록 하라고 권면한다. 

감사가 가득 차는 것만으로도 충분할 것 같은데, 바울은 한 걸음 더 나아가 “넘치도록” 감사하라고 말한다. 

그는 자신만 은혜 가운데 머무르기를 원하지 않았던 것 같다. 

연약한 자들, 세상의 철학과 전통에 미혹된 자들에게도 주님의 사랑과 진리를 전하고자 하는 마음이 그의 안에 가득하였다.

바울은 자신을 직접 만나본 적조차 없는 사람들에게도 간절한 마음을 품고 있었다. 

그는 예수 그리스도를 아는 지혜와 지식이 하나님께서 감추어 두신 보화라고 말한다. 

세상 어떤 것과도 비교할 수 없는 가장 값진 보화를 사람들에게 나누어 주고 싶었다.

만일 예수 그리스도의 보화 창고가 예수 안에 존재한다면, 신자는 당연히 예수를 깊이 만나고 알아 가는 삶으로 나아가야 할 것이다. 

바울은 예수 안에서 온전히 서기 위해 “뿌리를 박으라”고 권면한다. 

뿌리는 나무의 가장 중요한 부분 가운데 하나로, 물과 양분을 가장 먼저 공급받는 자리이다.

이처럼 신자도 말씀 묵상과 기도를 통해 예수 안에 깊이 뿌리내릴 때 은혜와 기쁨의 영적인 양분을 공급받게 된다. 

그리고 그때 삶은 흔들리지 않게 된다. 

나무 전체를 지켜 주고 다스리시는 하나님 안에서 충만한 일상을 살아가게 되는 것이다. 

결국 믿음의 뿌리가 깊어질수록 감사도 넘치게 되고, 그 감사는 다시 다른 영혼을 살리는 통로가 되는 것 같다.
 
9. 적용 (구체적으로)
예수 안에서 감사가 넘치는 사람이 되기를 바란다. 

더욱 기도와 말씀 묵상에 힘써야겠다.

10. 영적 터치 (단어/구절)
7절: 믿음에 굳게 서서 감사함을 넘치게 하라

11. 믿음과 회개 및 감사 기도로 마무리하기

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-05-11', '골로새서', '2장 11~23절', '제목 없음', '[골2:11-23]
11 또 그 안에서 너희가 손으로 하지 아니한 할례를 받았으니 곧 육의 몸을 벗는 것이요 그리스도의 할례니라
12 너희가 세례로 그리스도와 함께 장사되고 또 죽은 자들 가운데서 그를 일으키신 하나님의 역사를 믿음으로 말미암아 그 안에서 함께 일으키심을 받았느니라
13 또 범죄와 육체의 무할례로 죽었던 너희를 하나님이 그와 함께 살리시고 우리의 모든 죄를 사하시고
14 우리를 거스르고 불리하게 하는 법조문으로 쓴 증서를 지우시고 제하여 버리사 십자가에 못 박으시고
15 통치자들과 권세들을 무력화하여 드러내어 구경거리로 삼으시고 십자가로 그들을 이기셨느니라
16 그러므로 먹고 마시는 것과 절기나 초하루나 안식일을 이유로 누구든지 너희를 비판하지 못하게 하라
17 이것들은 장래 일의 그림자이나 몸은 그리스도의 것이니라
18 아무도 꾸며낸 겸손과 천사 숭배를 이유로 너희를 정죄하지 못하게 하라 그가 그 본 것에 의지하여 그 육신의 생각을 따라 헛되이 과장하고
19 머리를 붙들지 아니하는지라 온 몸이 머리로 말미암아 마디와 힘줄로 공급함을 받고 연합하여 하나님이 자라게 하시므로 자라느니라
