7.하나님 찾기(해석)

8.인간 찾기(해석)
- 자녀 교육을 할 때 훈계와 훈육은 반드시 필요하지만, 자녀가 노여워할 정도로 교육해서는 안 된다. 자녀가 낙심할 수 있기 때문이다. 
- 낙심하게 된 자녀는 무슨 일을 하든 힘 있게 해낼 수 없게 될 것이다.

- 신자는 무슨 일이 하든 예수님을 섬기는 마음으로 해야한다.
- 신자의 상은 예수님께서 주시는 것이기 때문이고, 또한 신자가 일을 하는 것은 주님을 섬기는 일이다. 
- 주님께서 주시는 상은 사람이 주는 상과 비교할 수 없는 것이다.

- 불의를 행하는 자는 반드시 불의의 보응을 받는다.
- 이 보응은 지위가 높고 낮음에 상관이 없다.

