2026년 05월 16일 
골로세서 4장 11절~18절
1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미 찾기:
문안: 11절 12절 14절 15절 18절
에바브라: 12절(2) 13절
