- 마지막으로 기도하길 권면하는 바울
- 전도의 문이 열리도록 기도를 요청하는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 감옥에 갇혀 있던 사도 바울의 관심은 복음이 전파되는 일이었다. 그는 자신의 억울함이나 안위를 위해 기도를 요청하지 않았다. 오히려 담대하게 복음을 전할 수 있도록 기도해 달라고 부탁한다. 이 말씀을 보며 요즘 점점 게을러지고 안일해진 나의 신앙을 돌아보게 된다.
- 인간적인 시선으로 보면 하나님께서 왜 바울을 감옥에 두셨는지 이해하기 어렵다. 바울이 자유롭게 다니며 전도하는 것이 더 많은 사람들에게 복음을 전할 수 있는 길처럼 보이기 때문이다. 그러나 하나님의 계획은 인간의 생각보다 훨씬 크고 깊다.
- 바울이 감옥에 갇힘으로 인해 옥중서신이 기록되었고, 그는 그곳에서도 하나님을 찬양하며 감사했고, 끝까지 복음을 증거했다. 그리고 그 기록들은 2000년이 지난 지금까지도 수많은 사람들의 삶을 변화시키고 있다. 당시에는 단지 ‘갇혀 있는 시간’처럼 보였을지 모르지만, 하나님께서는 그 시간을 통해 시대를 넘어서는 복음의 역사를 이루고 계셨던 것이다.
- 때로는 하나님의 계획과 나의 계획이 다를 수 있다. 나는 지금 당장 눈에 보이는 결과와 효율을 원하지만, 하나님께서는 내가 알지 못하는 더 크고 깊은 뜻을 이루고 계실 수 있다. 그러므로 우리는 이해되지 않는 상황 속에서도 하나님을 신뢰해야 한다. 지금은 알 수 없어도, 하나님께서는 다른 사람을 살리고 다음 세대를 세우기 위한 계획 가운데 우리를 사용하고 계실 수 있기 때문이다.

9. 적용(나): 
- 게을러진 마음을 바로 잡아주시도록 기도해야겠다.

10. 영적터치(단어/구절)
