- 이 거룩한 행동은 자신을 지키는 것이며, 나아가 주변 사람들에게 교회란 어떤 것인가 보여주는 것이다. 
- 신자를 통해 주변 불신자들이 예수님을 바라보게 되고 생각하게 된다.

- 데살로니가교회 형제들은 바울의 말을 하나님의 말씀으로 받았고, 이러한 태도는 이들이 얼마나 말씀을 사모하고 귀히 여기는 지 알 수 있는 부분이다.
- 신자는 말씀을 사람의 지혜있는 말이 아니라, 살아계신 하나님의 말씀으로 믿고 받아야 한다.
- 그래야 믿음 가운데 삶에서 능력이 나타난다. 하나님의 말씀은 사실이고, 살아있고 활력이 있다.

- 동족에게서 받는 고난은 괴롭지만, 예수님과 믿음의 선진들도 동일하거나 더 심한 고난을 받았다는 것을 기억해야 한다.
- 세상에서의 고난은 금방 지나가지만, 예수님과 함께 기쁨과 영광을 누리는 시간은 영원하다.

- 형제들의 믿음과 성장이 바울에게는 기쁨이요 자랑거리였다.
- 세상의 그 무엇이 아니라, 형제들의 믿음과 성장이 기쁨과 자랑거리라는 것은 바울 일행의 기준이 하늘에 있다는 것을 확실히 보여준다.
- 신자는 위의 것을 구할 때 순전한 기쁨을 누릴 수 있다.


9.적용(나) 
- 하나님 나라와 영광을 바라보며, 하나님께 합당한 삶을 살아야겠다.
- 바울 일행처럼 제자를 세우고 제자의 성장을 바라보며 순전한 기쁨을 누리는 자가 되도록 노력해야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-05-20', '데살로니가전서', '3장 1~13절', '제목 없음', '(데살로니가 전서 3장)
1. 이러므로 우리가 참다 못하여 우리만 아덴에 머물기를 좋게 생각하고
2. 우리 형제 곧 그리스도의 복음을 전하는 하나님의 일꾼인 디모데를 보내노니 이는 너희를 굳건하게 하고 너희 믿음에 대하여 위로함으로
3. 아무도 이 여러 환난 중에 흔들리지 않게 하려 함이라 우리가 이것을 위하여 세움 받은 줄을 너희가 친히 알리라
4. 우리가 너희와 함께 있을 때에 장차 받을 환난을 너희에게 미리 말하였는데 과연 그렇게 된 것을 너희가 아느니라
5. 이러므로 나도 참다 못하여 너희 믿음을 알기 위하여 그를 보내었노니 이는 혹 시험하는 자가 너희를 시험하여 우리 수고를 헛되게 할까 함이니
6. 지금은 디모데가 너희에게로부터 와서 너희 믿음과 사랑의 기쁜 소식을 우리에게 전하고 또 너희가 항상 우리를 잘 생각하여 우리가 너희를 간절히 보고자 함과 같이 너희도 우리를 간절히 보고자 한다 하니
7. 이러므로 형제들아 우리가 모든 궁핍과 환난 가운데서 너희 믿음으로 말미암아 너희에게 위로를 받았노라
8. 그러므로 너희가 주 안에 굳게 선즉 우리가 이제는 살리라
9. 우리가 우리 하나님 앞에서 너희로 말미암아 모든 기쁨으로 기뻐하니 너희를 위하여 능히 어떠한 감사로 하나님께 보답할까
10. 주야로 심히 간구함은 너희 얼굴을 보고 너희 믿음이 부족한 것을 보충하게 하려 함이라
11. 하나님 우리 아버지와 우리 주 예수는 우리 길을 너희에게로 갈 수 있게 하시오며
12. 또 주께서 우리가 너희를 사랑함과 같이 너희도 피차간과 모든 사람에 대한 사랑이 더욱 많아 넘치게 하사
13. 너희 마음을 굳건하게 하시고 우리 주 예수께서 그의 모든 성도와 함께 강림하실 때에 하나님 우리 아버지 앞에서 거룩함에 흠이 없게 하시기를 원하노라

