- 이들은 하나님을 사랑했으며 성령 충만을 받은 자들로 유추된다

- 하나님의 뜻은 신자의 거룩함이다. 신자는 음행을 멀리하고 또한 형제를 해야지 말아야 한다. 모든 일은 주께서 신원하여 주신다.
