- 복음을 믿는 자들에게는 주 예수 그리스도의 영광이 주어지고, 거부하는 자들에게는 미혹의 역사로 거짓 것을 믿게 되어 이 땅에서부터 심판의 길을 걷게 되는 것이다.

8.인간 찾기(해석)
- 신자가 하나님께 감사할 것은 우리가 구원을 선택한 것이 아니라, 하나님께서 우리를 선택하셔서 성령으로 거룩하게 하시고 믿음으로 구원에 이르게 하셨다는 것이다.
- 이를 위하여 복음으로 부르셨고 주 예수 그리스도의 영광에 이르게 하시는 것이다.
- 신자는 천국에서의 주 예수 그리스도의 영광을 함께 누리게 된다.
- 신자는 우리를 선택하시고 성령으로 거룩하게 하시고 믿음으로 구원하여 주신 하나님께 감사하고, 
- 이루시는 분은 하나님이시니 우리는 주 예수 그리스도의 영광을 함께 누리는 것을 소망으로 간직해야 한다.
- 이 하나님 나라 원리는 우리를 모든 고난과 역경을 이겨내는 인내의 원천이다.

- 주 예수 그리스도와 하나님께서 우리의 마음을 위로하시고 모든 좋은 일과 말에 굳건하게 하실 것이다.
- 신자의 마음을 위로하시는 분도 하나님이시고, 모든 좋은 일과 말에 굳건하게 하시는 분도 하나님이시니 우리는 겸손하게 하나님을 의지할 수 밖에 없다.
- 그래서 하나님을 의지하는 사람은 말씀과 기도의 삶을 살아가는 것이다.
- 말씀과 기도가 없으면 우린 아무것도 아니다.

9.적용(나) 
- 믿음의 역사와 사랑의 수고와 소망의 인내를 주시는 하나님께 감사하며, 
- 하나님을 의지하여 말씀과 기도로 승리하는 삶을 살아야겠다.

- 주 예수 그리스도의 영광에 참여하게 됨을 소망으로 간직해야 한다.

